const data = $input.first().json;
const NL = String.fromCharCode(10);
const CR = String.fromCharCode(13);
const TAB = String.fromCharCode(9);
const EPS = ['ε', 'epsilon', 'λ'];
const errors = [];
const warnings = [];
const norm = (s) => String(s == null ? '' : s).split(CR).join('').split(TAB).join(' ');
function pick(names, kws) {
  for (const n of names) { if (data[n] !== undefined) return data[n]; }
  for (const k of Object.keys(data)) {
    const lk = k.toLowerCase();
    for (const w of kws) { if (lk.indexOf(w) >= 0) return data[k]; }
  }
  return '';
}
const grammarText = norm(pick(['grammar'], ['gram']));
const start = norm(pick(['startSymbol'], ['inicial', 'start'])).trim();
const inputRaw = norm(pick(['inputString'], ['cadena', 'input'])).trim();
const multi = norm(pick(['multiTerminals'], ['varios', 'multi'])).split(',').map((s) => s.trim()).filter((s) => s.length > 0);

const rawLines = grammarText.split(NL);
const parsed = [];
const nts = [];
rawLines.forEach((line, idx) => {
  const ln = idx + 1;
  let t = line.trim();
  if (t.length === 0 || t[0] === '#') return;
  t = t.split('→').join('->').split('::=').join('->');
  const pos = t.indexOf('->');
  if (pos < 0) { errors.push('Línea ' + ln + ': falta el separador "->" (formato esperado: A -> aB | b).'); return; }
  const lhs = t.slice(0, pos).trim();
  if (lhs.length === 0) { errors.push('Línea ' + ln + ': falta el no terminal a la izquierda de "->".'); return; }
  if (lhs.indexOf(' ') >= 0) { errors.push('Línea ' + ln + ': el lado izquierdo "' + lhs + '" debe ser un único símbolo no terminal.'); return; }
  if (lhs.indexOf('|') >= 0 || lhs === '$' || EPS.indexOf(lhs) >= 0) { errors.push('Línea ' + ln + ': "' + lhs + '" no es un no terminal válido.'); return; }
  const rhs = t.slice(pos + 2);
  if (rhs.trim().length === 0) { errors.push('Línea ' + ln + ': el lado derecho está vacío (use ε para la cadena vacía).'); return; }
  const alts = rhs.split('|').map((a) => a.trim());
  alts.forEach((a, ai) => {
    if (a.length === 0) errors.push('Línea ' + ln + ': la alternativa ' + (ai + 1) + ' está vacía (use ε para la cadena vacía).');
  });
  if (nts.indexOf(lhs) < 0) nts.push(lhs);
  parsed.push({ ln: ln, lhs: lhs, alts: alts });
});
if (parsed.length === 0 && errors.length === 0) errors.push('La gramática está vacía. Escriba al menos una producción, por ejemplo: S -> aS | b');

const cands = [];
EPS.forEach((e) => cands.push({ s: e, k: 'eps' }));
multi.forEach((m) => {
  if (nts.indexOf(m) >= 0) errors.push('"' + m + '" está declarado como terminal de varios caracteres pero también es un no terminal.');
  else cands.push({ s: m, k: 't' });
});
nts.forEach((n) => cands.push({ s: n, k: 'nt' }));
cands.sort((a, b) => b.s.length - a.s.length);

const terminals = [];
const prods = [];
parsed.forEach((p) => {
  p.alts.forEach((alt) => {
    if (alt.length === 0) return;
    const tokens = [];
    const chunks = alt.split(' ').filter((c) => c.length > 0);
    chunks.forEach((chunk) => {
      const chars = Array.from(chunk);
      let i = 0;
      while (i < chunk.length) {
        let found = null;
        for (const c of cands) { if (chunk.startsWith(c.s, i)) { found = c; break; } }
        if (found) {
          tokens.push({ s: found.k === 'eps' ? 'ε' : found.s, k: found.k });
          i += found.s.length;
        } else {
          const cp = String.fromCodePoint(chunk.codePointAt(i));
          if (cp === '$') {
            errors.push('Línea ' + p.ln + ': el símbolo "$" está reservado para el fin de entrada y no puede usarse en producciones.');
          } else if (cp.length === 1 && cp >= 'A' && cp <= 'Z') {
            errors.push('Línea ' + p.ln + ': el símbolo "' + cp + '" parece un no terminal pero no tiene producciones definidas.');
          } else {
            tokens.push({ s: cp, k: 't' });
          }
          i += cp.length;
        }
      }
    });
    const hasEps = tokens.some((x) => x.k === 'eps');
    if (hasEps && tokens.length > 1) {
      errors.push('Línea ' + p.ln + ': ε debe aparecer sola en su alternativa ("' + alt + '").');
      return;
    }
    const rhsSyms = hasEps ? [] : tokens.map((x) => x.s);
    tokens.forEach((x) => { if (x.k === 't' && terminals.indexOf(x.s) < 0) terminals.push(x.s); });
    prods.push({ id: prods.length, lhs: p.lhs, rhs: rhsSyms });
  });
});

if (start.length === 0) errors.push('Debe indicar el símbolo inicial.');
else if (nts.indexOf(start) < 0 && parsed.length > 0) errors.push('El símbolo inicial "' + start + '" no tiene producciones en la gramática.');

const seen = {};
prods.forEach((p) => {
  const key = p.lhs + ' -> ' + p.rhs.join(' ');
  if (seen[key]) warnings.push('Producción duplicada: ' + key + '. Esto genera conflicto en la tabla.');
  seen[key] = true;
});
nts.forEach((n) => {
  if (n !== start) {
    const used = prods.some((p) => p.rhs.indexOf(n) >= 0);
    if (!used) warnings.push('El no terminal ' + n + ' no se usa en ninguna producción (inalcanzable).');
  }
});

const termSorted = terminals.slice().sort();
return [{ json: {
  ok: errors.length === 0,
  errors: errors,
  warnings: warnings,
  grammarText: grammarText,
  start: start,
  inputRaw: inputRaw,
  nts: nts,
  terminals: termSorted,
  multiTerminals: multi,
  prods: prods
} }];

const d = $input.first().json;
if (!d.ok) return [{ json: d }];
const ntset = new Set(d.nts);
const first = {};
d.nts.forEach((n) => { first[n] = new Set(); });
function firstOfSeq(seq) {
  const res = new Set();
  let allEps = true;
  for (const s of seq) {
    if (ntset.has(s)) {
      for (const x of first[s]) { if (x !== 'ε') res.add(x); }
      if (!first[s].has('ε')) { allEps = false; break; }
    } else {
      res.add(s);
      allEps = false;
      break;
    }
  }
  if (allEps) res.add('ε');
  return res;
}
let changed = true;
let guard = 0;
while (changed && guard < 10000) {
  changed = false;
  guard++;
  for (const p of d.prods) {
    const f = firstOfSeq(p.rhs);
    for (const x of f) {
      if (!first[p.lhs].has(x)) { first[p.lhs].add(x); changed = true; }
    }
  }
}
const order = (arr) => arr.slice().sort((a, b) => (a === 'ε') - (b === 'ε') || (a < b ? -1 : a > b ? 1 : 0));
const firstSets = {};
d.nts.forEach((n) => { firstSets[n] = order(Array.from(first[n])); });
const firstOfProds = d.prods.map((p) => order(Array.from(firstOfSeq(p.rhs))));
return [{ json: Object.assign({}, d, { firstSets: firstSets, firstOfProds: firstOfProds }) }];

const d = $input.first().json;
if (!d.ok) return [{ json: d }];
const ntset = new Set(d.nts);
const first = {};
d.nts.forEach((n) => { first[n] = new Set(d.firstSets[n]); });
function firstOfSeq(seq) {
  const res = new Set();
  let allEps = true;
  for (const s of seq) {
    if (ntset.has(s)) {
      for (const x of first[s]) { if (x !== 'ε') res.add(x); }
      if (!first[s].has('ε')) { allEps = false; break; }
    } else {
      res.add(s);
      allEps = false;
      break;
    }
  }
  if (allEps) res.add('ε');
  return res;
}
const follow = {};
d.nts.forEach((n) => { follow[n] = new Set(); });
follow[d.start].add('$');
let changed = true;
let guard = 0;
while (changed && guard < 10000) {
  changed = false;
  guard++;
  for (const p of d.prods) {
    for (let i = 0; i < p.rhs.length; i++) {
      const b = p.rhs[i];
      if (!ntset.has(b)) continue;
      const beta = p.rhs.slice(i + 1);
      const fb = firstOfSeq(beta);
      for (const x of fb) {
        if (x !== 'ε' && !follow[b].has(x)) { follow[b].add(x); changed = true; }
      }
      if (fb.has('ε')) {
        for (const x of follow[p.lhs]) {
          if (!follow[b].has(x)) { follow[b].add(x); changed = true; }
        }
      }
    }
  }
}
const order = (arr) => arr.slice().sort((a, b) => (a === '$') - (b === '$') || (a < b ? -1 : a > b ? 1 : 0));
const followSets = {};
d.nts.forEach((n) => { followSets[n] = order(Array.from(follow[n])); });
return [{ json: Object.assign({}, d, { followSets: followSets }) }];

const d = $input.first().json;
if (!d.ok) return [{ json: d }];
const columns = d.terminals.concat(['$']);
const table = {};
d.nts.forEach((n) => { table[n] = {}; });
function add(nt, t, id, via) {
  if (!table[nt][t]) table[nt][t] = [];
  if (!table[nt][t].some((e) => e.id === id && e.via === via)) table[nt][t].push({ id: id, via: via });
}
d.prods.forEach((p) => {
  const f = d.firstOfProds[p.id];
  f.forEach((t) => { if (t !== 'ε') add(p.lhs, t, p.id, 'FIRST'); });
  if (f.indexOf('ε') >= 0) {
    d.followSets[p.lhs].forEach((t) => add(p.lhs, t, p.id, 'FOLLOW'));
  }
});
const conflicts = [];
const cols2 = columns.slice();
d.nts.forEach((n) => {
  Object.keys(table[n]).forEach((t) => {
    const ids = Array.from(new Set(table[n][t].map((e) => e.id)));
    if (ids.length > 1) {
      const vias = new Set(table[n][t].map((e) => e.via));
      const kind = vias.has('FOLLOW') ? 'FIRST/FOLLOW' : 'FIRST/FIRST';
      conflicts.push({ nt: n, terminal: t, prods: ids, kind: kind });
    }
  });
});
const warnings = (d.warnings || []).slice();
d.prods.forEach((p) => {
  if (p.rhs.length > 0 && p.rhs[0] === p.lhs) {
    warnings.push('Recursión izquierda directa en ' + p.lhs + ' -> ' + p.rhs.join(' ') + ': la gramática no puede ser LL(1) y el análisis puede no terminar.');
  }
});
return [{ json: Object.assign({}, d, { columns: cols2, table: table, conflicts: conflicts, isLL1: conflicts.length === 0, warnings: warnings }) }];

const d = $input.first().json;
if (!d.ok) return [{ json: d }];
const EPS = ['ε', 'epsilon', 'λ'];
const ntset = new Set(d.nts);
const out = { provided: d.inputRaw.length > 0, accepted: false, tokens: [], steps: [], treeText: '', message: '', notes: [] };
if (!out.provided) {
  out.message = 'No se ingresó ninguna cadena; solo se calcularon FIRST, FOLLOW y la tabla.';
  return [{ json: Object.assign({}, d, { parse: out }) }];
}
let raw = d.inputRaw;
if (raw.length > 1 && raw[raw.length - 1] === '$') raw = raw.slice(0, raw.length - 1).trim();
else if (raw === '$') raw = '';
const termCands = d.terminals.concat(d.multiTerminals || []);
termCands.sort((a, b) => b.length - a.length);
let tokens = [];
let tokError = '';
if (raw.length > 0 && EPS.indexOf(raw) < 0) {
  const chunks = raw.split(' ').filter((c) => c.length > 0);
  for (const chunk of chunks) {
    let i = 0;
    while (i < chunk.length) {
      let found = null;
      for (const c of termCands) { if (chunk.startsWith(c, i)) { found = c; break; } }
      if (found) { tokens.push(found); i += found.length; }
      else {
        const cp = String.fromCodePoint(chunk.codePointAt(i));
        if (!tokError) tokError = 'El símbolo "' + cp + '" de la cadena no es un terminal de la gramática.';
        tokens.push(cp);
        i += cp.length;
      }
    }
  }
}
out.tokens = tokens;
if (tokError) {
  out.message = 'Cadena RECHAZADA: ' + tokError;
  out.treeText = '';
  return [{ json: Object.assign({}, d, { parse: out }) }];
}
if (!d.isLL1) out.notes.push('La gramática no es LL(1): en las celdas con conflicto se usa la primera producción, por lo que el resultado puede ser incompleto.');
const root = { sym: d.start, children: [] };
const stack = [{ sym: '$', children: [] }, root];
const toks = tokens.concat(['$']);
let pos = 0;
let error = '';
let accepted = false;
let count = 0;
const fmt = (arr) => arr.join(' ');
while (true) {
  count++;
  if (count > 3000 || stack.length > 1500) { error = 'Se detuvo el análisis: demasiados pasos (posible recursión izquierda o gramática cíclica).'; break; }
  const top = stack[stack.length - 1];
  const a = toks[pos];
  const stackStr = fmt(stack.map((s) => s.sym).reverse());
  const inStr = fmt(toks.slice(pos));
  if (top.sym === '$') {
    if (a === '$') { out.steps.push({ n: count, stack: stackStr, input: inStr, action: 'Aceptar' }); accepted = true; }
    else { error = 'Sobran símbolos de entrada: "' + a + '".'; out.steps.push({ n: count, stack: stackStr, input: inStr, action: 'Error' }); }
    break;
  }
  if (ntset.has(top.sym)) {
    const cell = d.table[top.sym][a];
    if (!cell || cell.length === 0) {
      error = 'La celda M[' + top.sym + ', ' + a + '] está vacía: no hay producción aplicable.';
      out.steps.push({ n: count, stack: stackStr, input: inStr, action: 'Error: M[' + top.sym + ', ' + a + '] vacía' });
      break;
    }
    const p = d.prods[cell[0].id];
    stack.pop();
    if (p.rhs.length === 0) {
      top.children = [{ sym: 'ε', children: [], eps: true }];
    } else {
      top.children = p.rhs.map((s) => ({ sym: s, children: [] }));
      for (let i = top.children.length - 1; i >= 0; i--) stack.push(top.children[i]);
    }
    out.steps.push({ n: count, stack: stackStr, input: inStr, action: p.lhs + ' → ' + (p.rhs.length ? fmt(p.rhs) : 'ε') });
  } else {
    if (top.sym === a) {
      stack.pop();
      pos++;
      out.steps.push({ n: count, stack: stackStr, input: inStr, action: 'Coincide "' + a + '"' });
    } else {
      error = 'Se esperaba "' + top.sym + '" pero se encontró "' + a + '".';
      out.steps.push({ n: count, stack: stackStr, input: inStr, action: 'Error: se esperaba ' + top.sym });
      break;
    }
  }
}
function render(node, prefix, isLast, isRoot, lines) {
  if (isRoot) lines.push(node.sym);
  else lines.push(prefix + (isLast ? '└── ' : '├── ') + node.sym);
  const kids = node.children || [];
  const np = isRoot ? '' : prefix + (isLast ? '    ' : '│   ');
  kids.forEach((k, i) => render(k, np, i === kids.length - 1, false, lines));
}
const lines = [];
render(root, '', true, true, lines);
out.treeText = lines.join(String.fromCharCode(10));
out.accepted = accepted;
out.partialTree = !accepted;
out.message = accepted ? 'Cadena ACEPTADA' : 'Cadena RECHAZADA: ' + error;
return [{ json: Object.assign({}, d, { parse: out }) }];

const d = $input.first().json;
const esc = (s) => String(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');
const TH = 'style="background:#2d3748;color:#fff;padding:6px 10px;border:1px solid #999;text-align:left"';
const TD = 'style="padding:6px 10px;border:1px solid #bbb;vertical-align:top"';
const box = (bg, fg, html) => '<div style="background:' + bg + ';color:' + fg + ';padding:10px 14px;border-radius:6px;margin:10px 0;font-weight:bold">' + html + '</div>';
const h = (t) => '<h3 style="margin:22px 0 8px;border-bottom:2px solid #ddd;padding-bottom:4px">' + esc(t) + '</h3>';
const tbl = (inner) => '<table border="1" cellspacing="0" style="border-collapse:collapse;font-family:monospace;font-size:14px">' + inner + '</table>';
let html = '<div style="text-align:left;max-width:1000px;overflow-x:auto">';

if (!d.ok) {
  html += box('#fed7d7', '#9b2c2c', 'ERROR: la gramática o los datos de entrada no son válidos');
  html += '<ul>' + d.errors.map((e) => '<li>' + esc(e) + '</li>').join('') + '</ul>';
  html += '<p>Formato esperado, una producción por línea: <code>A -> aB | b</code>. Use <code>ε</code> para la cadena vacía. Los no terminales son los símbolos que aparecen a la izquierda de "->". Separe los símbolos con espacios o escríbalos juntos; para terminales de varios caracteres (por ejemplo id) decláreelos en el campo correspondiente. El símbolo $ está reservado.</p>';
  html += '</div>';
  return [{ json: { html: html } }];
}

const fmtSet = (arr) => '{ ' + arr.map(esc).join(', ') + ' }';
const prodStr = (p) => esc(p.lhs) + ' → ' + (p.rhs.length ? esc(p.rhs.join(' ')) : 'ε');

html += h('1. Producciones (símbolo inicial: ' + d.start + ')');
html += tbl('<tr><th ' + TH + '>#</th><th ' + TH + '>Producción</th></tr>' + d.prods.map((p) => '<tr><td ' + TD + '>' + p.id + '</td><td ' + TD + '>' + prodStr(p) + '</td></tr>').join(''));
html += '<p>No terminales: ' + fmtSet(d.nts) + '<br>Terminales: ' + fmtSet(d.terminals.concat(['$'])) + '</p>';
if (d.warnings && d.warnings.length) {
  html += box('#fefcbf', '#744210', 'Advertencias') + '<ul>' + d.warnings.map((w) => '<li>' + esc(w) + '</li>').join('') + '</ul>';
}

html += h('2. Conjuntos FIRST');
html += tbl('<tr><th ' + TH + '>No terminal</th><th ' + TH + '>FIRST</th></tr>' + d.nts.map((n) => '<tr><td ' + TD + '>' + esc(n) + '</td><td ' + TD + '>' + fmtSet(d.firstSets[n]) + '</td></tr>').join(''));

html += h('3. Conjuntos FOLLOW');
html += tbl('<tr><th ' + TH + '>No terminal</th><th ' + TH + '>FOLLOW</th></tr>' + d.nts.map((n) => '<tr><td ' + TD + '>' + esc(n) + '</td><td ' + TD + '>' + fmtSet(d.followSets[n]) + '</td></tr>').join(''));

html += h('4. Matriz predictiva LL(1)');
let head = '<tr><th ' + TH + '>M</th>' + d.columns.map((c) => '<th ' + TH + '>' + esc(c) + '</th>').join('') + '</tr>';
let rows = d.nts.map((n) => {
  return '<tr><td ' + TD + '><b>' + esc(n) + '</b></td>' + d.columns.map((c) => {
    const cell = d.table[n][c];
    if (!cell) return '<td ' + TD + '></td>';
    const ids = Array.from(new Set(cell.map((e) => e.id)));
    const txt = ids.map((id) => prodStr(d.prods[id])).join('<br>');
    const bg = ids.length > 1 ? 'background:#fed7d7;' : '';
    return '<td style="padding:6px 10px;border:1px solid #bbb;vertical-align:top;' + bg + '">' + txt + '</td>';
  }).join('') + '</tr>';
}).join('');
html += tbl(head + rows);
if (d.isLL1) {
  html += box('#c6f6d5', '#22543d', 'La gramática ES LL(1): no hay conflictos en la matriz predictiva.');
} else {
  html += box('#fed7d7', '#9b2c2c', 'La gramática NO es LL(1): se encontraron ' + d.conflicts.length + ' conflicto(s).');
  html += '<ul>' + d.conflicts.map((c) => '<li>M[' + esc(c.nt) + ', ' + esc(c.terminal) + '] (' + c.kind + '): ' + c.prods.map((id) => prodStr(d.prods[id])).join('  |  ') + '</li>').join('') + '</ul>';
}

html += h('5. Análisis de la cadena');
const pr = d.parse;
if (!pr.provided) {
  html += '<p>' + esc(pr.message) + '</p>';
} else {
  html += '<p>Cadena: <code>' + esc(d.inputRaw) + '</code> &nbsp; Tokens: ' + fmtSet(pr.tokens.concat(['$'])) + '</p>';
  html += pr.accepted ? box('#c6f6d5', '#22543d', esc(pr.message)) : box('#fed7d7', '#9b2c2c', esc(pr.message));
  if (pr.notes && pr.notes.length) html += '<ul>' + pr.notes.map((n) => '<li>' + esc(n) + '</li>').join('') + '</ul>';
  if (pr.steps.length) {
    html += '<h4>Traza del análisis</h4>';
    html += tbl('<tr><th ' + TH + '>Paso</th><th ' + TH + '>Pila (tope a la izquierda)</th><th ' + TH + '>Entrada</th><th ' + TH + '>Acción</th></tr>' + pr.steps.map((s) => '<tr><td ' + TD + '>' + s.n + '</td><td ' + TD + '>' + esc(s.stack) + '</td><td ' + TD + '>' + esc(s.input) + '</td><td ' + TD + '>' + esc(s.action) + '</td></tr>').join(''));
  }
  if (pr.treeText) {
    html += '<h4>' + (pr.accepted ? 'Árbol de derivación' : 'Árbol parcial (hasta el punto del error)') + '</h4>';
    html += '<pre style="background:#f7fafc;border:1px solid #ddd;padding:10px;font-size:15px;line-height:1.35">' + esc(pr.treeText) + '</pre>';
  }
}
html += '</div>';
return [{ json: { html: html } }];
